import AppKit
import Combine

/// Watches the pasteboard, records clips per source app and persists them in Application Support.
final class ClipStore: ObservableObject {
    static let shared = ClipStore()
    static let unknownKey = "unknown"
    static let maxTextLength = 200_000
    private static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]

    @Published private(set) var clips: [Clip] = []
    @Published var notice: String?
    private(set) var loadWarning: String?

    private let fm = FileManager.default
    private let baseDir: URL
    private let imagesDir: URL
    private let iconsDir: URL
    private var historyURL: URL { baseDir.appendingPathComponent("history.json") }
    private var timer: Timer?
    private var lastChange = NSPasteboard.general.changeCount
    private var pendingSave: DispatchWorkItem?
    private var iconCache: [String: NSImage] = [:]
    private var thumbCache: [String: NSImage] = [:]

    private init() {
        let support = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask).first ?? fm.temporaryDirectory
        baseDir = support.appendingPathComponent("AppGroupedClips", isDirectory: true)
        imagesDir = baseDir.appendingPathComponent("Images", isDirectory: true)
        iconsDir = baseDir.appendingPathComponent("Icons", isDirectory: true)
        for dir in [baseDir, imagesDir, iconsDir] {
            try? fm.createDirectory(at: dir, withIntermediateDirectories: true)
        }
        load()
    }

    // MARK: - Derived data

    var favorites: [Clip] { clips.filter(\.isFavorite) }

    var groups: [AppGroup] {
        Dictionary(grouping: clips, by: \.appKey).map { key, items in
            AppGroup(key: key, name: items.first?.appName ?? "Unknown", count: items.count,
                     latest: items.map(\.date).max() ?? .distantPast)
        }
        .sorted { $0.latest > $1.latest }
    }

    static var ignoredBundleIDs: [String] {
        (UserDefaults.standard.string(forKey: "ignoredApps") ?? "")
            .split(separator: "\n").map(String.init).filter { !$0.isEmpty }
    }

    // MARK: - Monitoring

    func start() {
        guard timer == nil else { return }
        let t = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        let types = pb.types ?? []
        if types.contains(where: { Self.skippedTypes.contains($0.rawValue) }) { return }

        let front = NSWorkspace.shared.frontmostApplication
        let bundleID = front?.bundleIdentifier
        if let b = bundleID, b == Bundle.main.bundleIdentifier || Self.ignoredBundleIDs.contains(b) { return }
        let appName = front?.localizedName ?? "Unknown"

        var clip = Clip(kind: .text, appName: bundleID == nil ? "Unknown" : appName, bundleID: bundleID, date: Date())
        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            clip.kind = .files
            clip.text = urls.map(\.path).joined(separator: "\n")
        } else if let s = pb.string(forType: .string), !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let trimmed = s.trimmingCharacters(in: .whitespacesAndNewlines)
            let isLink = !trimmed.contains(" ") && !trimmed.contains("\n")
                && (URL(string: trimmed)?.scheme.map { ["http", "https", "mailto", "ftp"].contains($0) } ?? false)
            clip.kind = isLink ? .link : .text
            if s.count > Self.maxTextLength {
                clip.text = String(s.prefix(Self.maxTextLength))
                    + "\n\n… [truncated — original was \(s.count) characters]"
                clip.truncated = true
            } else {
                clip.text = s
            }
        } else if let u = pb.string(forType: .URL) {
            clip.kind = .link
            clip.text = u
        } else if UserDefaults.standard.bool(forKey: "captureImages"), let png = pngData(from: pb) {
            if let first = clips.first, first.kind == .image, let file = first.imageFile,
               (try? Data(contentsOf: imagesDir.appendingPathComponent(file))) == png {
                bump(at: 0)
                return
            }
            let name = "\(clip.id.uuidString).png"
            do { try png.write(to: imagesDir.appendingPathComponent(name)) } catch { return }
            clip.kind = .image
            clip.imageFile = name
        } else {
            return
        }

        cacheIcon(front?.icon, key: clip.appKey)
        if let first = clips.first, first.sameContent(as: clip) {
            bump(at: 0)
            return
        }
        clips.insert(clip, at: 0)
        enforceLimit(for: clip.appKey)
        scheduleSave()
    }

    private func pngData(from pb: NSPasteboard) -> Data? {
        if let png = pb.data(forType: .png) { return png }
        guard let tiff = pb.data(forType: .tiff), let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }

    private func bump(at index: Int) {
        guard clips.indices.contains(index) else { return }
        var c = clips.remove(at: index)
        c.date = Date()
        clips.insert(c, at: 0)
        scheduleSave()
    }

    private func enforceLimit(for key: String) {
        let limit = min(500, max(20, UserDefaults.standard.integer(forKey: "maxPerApp")))
        while clips.filter({ $0.appKey == key }).count > limit,
              let idx = clips.lastIndex(where: { $0.appKey == key && !$0.isFavorite }) {
            removeFiles(of: clips.remove(at: idx))
        }
    }

    // MARK: - Mutations

    func toggleFavorite(_ id: UUID) {
        guard let i = clips.firstIndex(where: { $0.id == id }) else { return }
        clips[i].isFavorite.toggle()
        scheduleSave()
    }

    func rename(_ id: UUID, to label: String) {
        guard let i = clips.firstIndex(where: { $0.id == id }) else { return }
        let t = label.trimmingCharacters(in: .whitespacesAndNewlines)
        clips[i].label = t.isEmpty ? nil : t
        if !t.isEmpty { clips[i].isFavorite = true }
        scheduleSave()
    }

    func delete(_ ids: Set<UUID>) {
        clips.filter { ids.contains($0.id) }.forEach(removeFiles)
        clips.removeAll { ids.contains($0.id) }
        scheduleSave()
    }

    func clear(keepFavorites: Bool) {
        let removed = clips.filter { !keepFavorites || !$0.isFavorite }
        removed.forEach(removeFiles)
        clips.removeAll { !keepFavorites || !$0.isFavorite }
        scheduleSave()
    }

    func neverRecord(from bundleID: String?) {
        guard let b = bundleID else { return }
        var list = Self.ignoredBundleIDs
        guard !list.contains(b) else { return }
        list.append(b)
        UserDefaults.standard.set(list.joined(separator: "\n"), forKey: "ignoredApps")
    }

    /// Writes a clip back to the general pasteboard without re-recording it.
    func writeToPasteboard(_ clip: Clip) {
        let pb = NSPasteboard.general
        pb.clearContents()
        switch clip.kind {
        case .image:
            if let file = clip.imageFile, let data = try? Data(contentsOf: imagesDir.appendingPathComponent(file)) {
                pb.setData(data, forType: .png)
                if let tiff = NSImage(data: data)?.tiffRepresentation { pb.setData(tiff, forType: .tiff) }
            }
        case .files:
            let urls = (clip.text ?? "").split(separator: "\n").map { URL(fileURLWithPath: String($0)) }
                .filter { fm.fileExists(atPath: $0.path) }
            if !urls.isEmpty { pb.writeObjects(urls as [NSURL]) }
            pb.setString(clip.text ?? "", forType: .string)
        case .link:
            pb.setString(clip.text ?? "", forType: .string)
            pb.setString(clip.text ?? "", forType: .URL)
        case .text:
            pb.setString(clip.text ?? "", forType: .string)
        }
        lastChange = pb.changeCount
    }

    private func removeFiles(of clip: Clip) {
        guard let file = clip.imageFile else { return }
        thumbCache[file] = nil
        try? fm.removeItem(at: imagesDir.appendingPathComponent(file))
    }

    // MARK: - Images & icons

    func thumbnail(for clip: Clip) -> NSImage? {
        guard let file = clip.imageFile else { return nil }
        if let cached = thumbCache[file] { return cached }
        let image = NSImage(contentsOf: imagesDir.appendingPathComponent(file))
        thumbCache[file] = image
        return image
    }

    func icon(for key: String) -> NSImage {
        if let cached = iconCache[key] { return cached }
        var image: NSImage?
        if key != Self.unknownKey {
            if let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: key) {
                image = NSWorkspace.shared.icon(forFile: url.path)
            } else {
                image = NSImage(contentsOf: iconsDir.appendingPathComponent("\(key).png"))
            }
        }
        let result = image ?? NSImage(systemSymbolName: "questionmark.app.dashed", accessibilityDescription: "Unknown app")
            ?? NSImage()
        iconCache[key] = result
        return result
    }

    /// Saves a small PNG of the app icon so it still shows after the app is gone.
    private func cacheIcon(_ icon: NSImage?, key: String) {
        guard key != Self.unknownKey, let icon else { return }
        let url = iconsDir.appendingPathComponent("\(key).png")
        guard !fm.fileExists(atPath: url.path) else { return }
        let size = NSSize(width: 64, height: 64)
        guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: 64, pixelsHigh: 64, bitsPerSample: 8,
                                         samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                                         colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0) else { return }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
        icon.draw(in: NSRect(origin: .zero, size: size))
        NSGraphicsContext.restoreGraphicsState()
        try? rep.representation(using: .png, properties: [:])?.write(to: url)
    }

    // MARK: - Persistence

    private func load() {
        guard fm.fileExists(atPath: historyURL.path) else { return }
        do {
            let data = try Data(contentsOf: historyURL)
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            clips = try decoder.decode([Clip].self, from: data).sorted { $0.date > $1.date }
        } catch {
            let f = DateFormatter()
            f.dateFormat = "yyyy-MM-dd-HHmmss"
            let dest = baseDir.appendingPathComponent("history-corrupt-\(f.string(from: Date())).json")
            try? fm.moveItem(at: historyURL, to: dest)
            loadWarning = "Your clipboard history could not be read, so it was moved aside to “\(dest.lastPathComponent)” and a fresh history was started."
        }
    }

    private func scheduleSave() {
        pendingSave?.cancel()
        let work = DispatchWorkItem { [weak self] in self?.saveNow() }
        pendingSave = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5, execute: work)
    }

    func saveNow() {
        pendingSave?.cancel()
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        do {
            try encoder.encode(clips).write(to: historyURL, options: .atomic)
        } catch {
            NSLog("AppGroupedClips: failed to save history: \(error.localizedDescription)")
        }
    }
}
